class Words2Numbers:

    MAGIC_AND_SCALE = (1, 0)
    MAGIC_HUNDRED_SCALE = 100
    MAGIC_THOUSAND_SCALE = 10 ** 3
    MAGIC_MILLION_SCALE = 10 ** 6
    MAGIC_BILLION_SCALE = 10 ** 9
    MAGIC_TRILLION_SCALE = 10 ** 12

    def __init__(self):
        self.numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = [
            (self.MAGIC_HUNDRED_SCALE, 0),
            (self.MAGIC_THOUSAND_SCALE, 0),
            (self.MAGIC_MILLION_SCALE, 0),
            (self.MAGIC_BILLION_SCALE, 0),
            (self.MAGIC_TRILLION_SCALE, 0),
        ]

        self.numwords["and"] = self.MAGIC_AND_SCALE
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            self.numwords[word] = (1, idx * 10)
        for idx, (scale_value, _) in enumerate(self.scales):
            self.numwords[self.scales[0][0] if idx == 0 else self._scale_name(idx)] = (scale_value, 0)

        self.ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]

    def _scale_name(self, idx):
        # Reconstruct scale names for lookup consistency
        if idx == 0:
            return "hundred"
        elif idx == 1:
            return "thousand"
        elif idx == 2:
            return "million"
        elif idx == 3:
            return "billion"
        elif idx == 4:
            return "trillion"
        return "unknown"

    def _normalize_ordinal_word(self, word):
        for ending, replacement in self.ordinal_endings:
            if word.endswith(ending):
                return "%s%s" % (word[:-len(ending)], replacement)
        return word

    def _get_scale_increment(self, word):
        if word in self.ordinal_words:
            return (1, self.ordinal_words[word])
        elif word in self.numwords:
            return self.numwords[word]
        return None

    def text2int(self, textnum):
        textnum = textnum.replace('-', ' ')

        current = 0
        result = 0
        curstring = ""
        onnumber = False

        for word in textnum.split():
            normalized_word = self._normalize_ordinal_word(word)
            scale_increment = self._get_scale_increment(normalized_word)

            if scale_increment is not None:
                scale, increment = scale_increment
                current = current * scale + increment
                onnumber = True

                if scale > self.MAGIC_HUNDRED_SCALE:
                    result += current
                    current = 0
            else:
                if onnumber:
                    curstring += repr(result + current) + " "
                curstring += word + " "
                result = 0
                current = 0
                onnumber = False

        if onnumber:
            curstring += repr(result + current)

        return curstring

    def is_valid_input(self, textnum):
        textnum = textnum.replace('-', ' ')

        for word in textnum.split():
            if word in self.ordinal_words:
                continue

            normalized_word = self._normalize_ordinal_word(word)
            if normalized_word not in self.numwords:
                return False

        return True
